function createParser(options = {}) {
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new RangeError("delimiter must be a single character other than '\"', '\\r', or '\\n'");
