  function completeRecord(out) {
    fields.push(field);
    out.push(fields);
    fields = [];
    field = '';
    state = 'start';
  }

  function hasPendingRecord() {
    return fields.length > 0 || field.length > 0 || state === 'quoted' || state === 'afterQuote';
  }

  function push(chunk) {
    if (ended) throw new Error('push() called after end()');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
    const out = [];
    for (let i = 0; i < chunk.length; i++) {
