        if (state === 'quoted') field += c;
        else completeRecord(out);
        continue;
      }
      if (state === 'afterQuote') {
        if (c === '"') {
          field += '"';
          state = 'quoted';
        } else if (c === delimiter) {
          fields.push(field);
          field = '';
          state = 'start';
        } else {
          throw new SyntaxError(`Unexpected character after closing quote (line ${line})`);
        }
        continue;
      }
      if (state === 'quoted') {
        if (c === '"') state = 'afterQuote';
        else field += c;
        continue;
      }
      // 'start' or 'unquoted'
      if (c === delimiter) {
        fields.push(field);
        field = '';
        state = 'start';
      } else if (c === '"') {
        if (state === 'start') state = 'quoted';
        else field += c;
      } else {
        field += c;
        state = 'unquoted';
      }
    }
    return out;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === 'quoted') {
      throw new SyntaxError(`Unterminated quoted field (line ${line})`);
    }
    if (!hasPendingRecord()) return [];
    const out = [];
    completeRecord(out);
    return out;
  }

  return { push, end };
