  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new RangeError(
      'delimiter must be one UTF-16 code unit other than \'"\', \'\\r\', or \'\\n\''
    );
  }

  let ended = false;
  let firstChar = true; // no input character consumed yet (BOM may still be stripped)
  let skipLF = false; // previous character was CR; a following LF is part of the same CRLF
  let line = 1; // 1-based physical line of the character being processed
  let state = 'start'; // 'start' | 'unquoted' | 'quoted' | 'afterQuote'
  let field = '';
  let fields = [];

  function completeRecord(out) {
    fields.push(field);
    out.push(fields);
    fields = [];
    field = '';
    state = 'start';
  }

  function hasPendingRecord() {
    return (
      fields.length > 0 ||
      field.length > 0 ||
      state === 'quoted' ||
      state === 'afterQuote'
    );
  }

  function push(chunk) {
    if (ended) throw new Error('push() called after end()');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
