    for (let i = 0; i < chunk.length; i++) {
      const c = chunk[i];
      if (firstChar) {
        firstChar = false;
        if (c === '\uFEFF') continue;
      }
      if (skipLF) {
        skipLF = false;
        if (c === '\n') {
          // Second half of a CRLF: already counted and (outside quotes) the
          // record was already completed at the CR.
          if (state === 'quoted') field += c;
          continue;
        }
