        line++;
        skipLF = true;
        if (state === 'quoted') field += c;
        else completeRecord(out);
        continue;
      }
      if (c === '\n') {
        line++;
        if (state === 'quoted') field += c;
        else completeRecord(out);
        continue;
      }
      if (state === 'afterQuote') {
        if (c === '"') {
          field += '"';
          state = 'quoted';
        } else if (c === delimiter) {
          fields.push(field);
          field = '';
          state = 'start';
        } else {
          throw new SyntaxError(
            `Unexpected character after closing quote (line ${line})`
          );
        }
        continue;
      }
      if (state === 'quoted') {
        if (c === '"') state = 'afterQuote';
        else field += c;
        continue;
      }
      // state is 'start' or 'unquoted'
      if (c === delimiter) {
        fields.push(field);
        field = '';
        state = 'start';
