    fields.push(field);
    out.push(fields);
    fields = [];
    field = '';
    state = 'start';
  }

  function hasPendingRecord() {
    return (
      fields.length > 0 ||
      field.length > 0 ||
      state === 'quoted' ||
      state === 'afterQuote'
    );
