        if (state === 'quoted') field += c;
        else completeRecord(out);
        continue;
      }
      if (c === '\n') {
        line++;
        if (state === 'quoted') field += c;
        else completeRecord(out);
        continue;
      }
      if (state === 'afterQuote') {
        if (c === '"') {
          field += '"';
          state = 'quoted';
        } else if (c === delimiter) {
          fields.push(field);
          field = '';
          state = 'start';
        } else {
