      } else {
        field += c;
        state = 'unquoted';
      }
    }
    return out;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === 'quoted') {
      throw new SyntaxError(`Unterminated quoted field (line ${line})`);
    }
    if (!hasPendingRecord()) return [];
    const out = [];
    completeRecord(out);
    return out;
  }

  return { push, end };
}

